package com.peiwan.platform.fulfillment;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;import com.baomidou.mybatisplus.core.conditions.update.UpdateWrapper;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import com.peiwan.platform.persistence.entity.*;import com.peiwan.platform.persistence.mapper.*;import com.peiwan.platform.order.OrderMemberService;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.*;
@Service public class FulfillmentService{
 private final FulfillmentMapper fulfillments;private final FulfillmentProofMapper proofs;private final FulfillmentAuditMapper audits;private final FulfillmentDataMapper data;private final PlayerMapper players;private final OrderMapper orders;private final OrderStatusLogMapper orderLogs;private final OrderMemberService orderMembers;
 public FulfillmentService(FulfillmentMapper fulfillments,FulfillmentProofMapper proofs,FulfillmentAuditMapper audits,FulfillmentDataMapper data,PlayerMapper players,OrderMapper orders,OrderStatusLogMapper orderLogs,OrderMemberService orderMembers){this.fulfillments=fulfillments;this.proofs=proofs;this.audits=audits;this.data=data;this.players=players;this.orders=orders;this.orderLogs=orderLogs;this.orderMembers=orderMembers;}
 @Transactional public void start(long userId,long orderId){var p=player(userId);var o=ownOrder(orderId,p.id);if(!Set.of("ASSIGNED","IN_SERVICE").contains(o.orderStatus))throw new IllegalArgumentException("当前订单不能开始服务");var member=data.activeMember(orderId,p.id);if(member==null)throw new IllegalArgumentException("当前成员已不在役");long memberId=((Number)member.get("id")).longValue();data.startMember(memberId);var f=fulfillments.selectOne(new QueryWrapper<FulfillmentEntity>().eq("order_member_id",memberId));if(f==null){f=new FulfillmentEntity();f.orderId=orderId;f.orderMemberId=memberId;f.playerId=p.id;f.fulfillmentStatus="IN_SERVICE";fulfillments.insert(f);}if("ASSIGNED".equals(o.orderStatus)){o.orderStatus="IN_SERVICE";o.serviceStartedAt=LocalDateTime.now();o.updatedAt=LocalDateTime.now();orders.updateById(o);logOrder(orderId,"ASSIGNED","IN_SERVICE",userId,"订单成员开始服务");}}
 @Transactional public void submit(long userId,long orderId,Submit c){var p=player(userId);var o=ownOrder(orderId,p.id);if(!"IN_SERVICE".equals(o.orderStatus))throw new IllegalArgumentException("只有服务中订单可以提交完成凭证");if(c.completionNote()==null||c.completionNote().isBlank())throw new IllegalArgumentException("请填写完成说明");if(c.proofUrls()==null||c.proofUrls().isEmpty())throw new IllegalArgumentException("请至少上传一项完成凭证");if(c.proofUrls().size()>9)throw new IllegalArgumentException("完成凭证最多9项");var member=data.activeMember(orderId,p.id);if(member==null)throw new IllegalArgumentException("当前成员已不在役");if(!"IN_SERVICE".equals(member.get("member_status")))throw new IllegalArgumentException("请先开始服务，再提交完成凭证");long memberId=((Number)member.get("id")).longValue();var f=fulfillments.selectOne(new QueryWrapper<FulfillmentEntity>().eq("order_member_id",memberId));if(f==null)throw new IllegalArgumentException("请先开始服务，再提交完成凭证");String before=f.fulfillmentStatus;if("PENDING_REVIEW".equals(before)||"COMPLETED".equals(before))throw new IllegalArgumentException("你已经提交过完成凭证");fulfillments.update(null,new UpdateWrapper<FulfillmentEntity>().eq("id",f.id).set("fulfillment_status","PENDING_REVIEW").set("completion_note",c.completionNote()).set("actual_quantity",c.actualQuantity()).set("submitted_at",LocalDateTime.now()).set("review_remark",null).set("updated_at",LocalDateTime.now()));proofs.delete(new QueryWrapper<FulfillmentProofEntity>().eq("fulfillment_id",f.id));int i=0;for(String url:c.proofUrls())if(url!=null&&!url.isBlank()){var proof=new FulfillmentProofEntity();proof.fulfillmentId=f.id;proof.proofType="MEDIA";proof.proofUrl=url;proof.sortNo=i++;proofs.insert(proof);}audit(f.id,"SUBMIT",before,"PENDING_REVIEW","成员提交完成凭证",userId);if(data.submittedCount(orderId)==data.activeMemberCount(orderId)){o.orderStatus="PENDING_CONFIRM";o.completionSubmittedAt=LocalDateTime.now();o.updatedAt=LocalDateTime.now();orders.updateById(o);logOrder(orderId,"IN_SERVICE","PENDING_CONFIRM",userId,"当前在役成员已全部提交完成凭证");}}
 public Map<String,Object> list(int current,int size,String status){current=Math.max(1,current);size=Math.min(100,Math.max(1,size));var result=data.fulfillments(new Page<>(current,size),status);return Map.of("records",result.getRecords().stream().map(this::view).toList(),"current",current,"size",size,"total",result.getTotal());}
 public Map<String,Object> detail(long id){var row=data.detail(id);if(row==null)throw new IllegalArgumentException("履约记录不存在");var x=new LinkedHashMap<>(view(row));x.put("proofUrls",data.proofUrls(id));x.put("audits",data.audits(id));return x;}
 @Transactional public void review(long id,String action,String remark,long operator){var f=fulfillments.selectById(id);if(f==null)throw new IllegalArgumentException("履约记录不存在");if(!"PENDING_REVIEW".equals(f.fulfillmentStatus))throw new IllegalArgumentException("只有待审核记录可以处理");var o=orders.selectById(f.orderId);if(o==null)throw new IllegalArgumentException("订单不存在");if("REJECT".equals(action)){if(remark==null||remark.isBlank())throw new IllegalArgumentException("驳回必须填写原因");reviewFields(f,"REJECTED",remark,operator);o.orderStatus="IN_SERVICE";o.updatedAt=LocalDateTime.now();orders.updateById(o);logOrder(o.id,"PENDING_CONFIRM","IN_SERVICE",operator,"成员完成凭证驳回："+remark);audit(id,"REJECT","PENDING_REVIEW","REJECTED",remark,operator);return;}if(!"APPROVE".equals(action))throw new IllegalArgumentException("审核动作无效");reviewFields(f,"COMPLETED",remark,operator);audit(id,"APPROVE","PENDING_REVIEW","COMPLETED",remark,operator);if(data.approvedCount(f.orderId)==data.activeMemberCount(f.orderId)){Integer hours=data.confirmHours();if(hours==null)throw new IllegalArgumentException("未配置订单确认规则");o.orderStatus="WAIT_CUSTOMER_CONFIRM";o.customerConfirmDeadline=LocalDateTime.now().plusHours(hours);o.updatedAt=LocalDateTime.now();orders.updateById(o);logOrder(o.id,"PENDING_CONFIRM","WAIT_CUSTOMER_CONFIRM",operator,"全员完成凭证审核通过，等待用户确认");}}
 private void reviewFields(FulfillmentEntity f,String status,String remark,long operator){f.fulfillmentStatus=status;f.reviewedBy=operator;f.reviewedAt=LocalDateTime.now();f.reviewRemark=remark;f.updatedAt=LocalDateTime.now();fulfillments.updateById(f);}
 private PlayerEntity player(long uid){var p=players.selectOne(new QueryWrapper<PlayerEntity>().eq("user_id",uid).eq("enabled",true).eq("audit_status","APPROVED"));if(p==null)throw new IllegalArgumentException("当前账号未绑定可用的陪玩师资料");return p;}private OrderEntity ownOrder(long oid,long pid){var o=orders.selectById(oid);if(o==null||!orderMembers.belongs(oid,pid))throw new IllegalArgumentException("订单不存在或不属于当前陪玩师");return o;}
 private void logOrder(long o,String from,String to,long op,String reason){var l=new OrderStatusLogEntity();l.orderId=o;l.fromStatus=from;l.toStatus=to;l.operatorId=op;l.reason=reason;orderLogs.insert(l);}private void audit(long f,String action,String from,String to,String remark,long op){var a=new FulfillmentAuditEntity();a.fulfillmentId=f;a.action=action;a.beforeStatus=from;a.afterStatus=to;a.remark=remark;a.operatorId=op;audits.insert(a);}
 private Map<String,Object> view(Map<String,Object>r){var x=new LinkedHashMap<String,Object>();String[][]k={{"id","id"},{"orderId","order_id"},{"orderNo","order_no"},{"orderStatus","order_status"},{"playerId","player_id"},{"playerName","player_name"},{"playerNo","player_no"},{"productName","product_name"},{"fulfillmentStatus","fulfillment_status"},{"completionNote","completion_note"},{"actualQuantity","actual_quantity"},{"submittedAt","submitted_at"},{"reviewRemark","review_remark"},{"reviewedAt","reviewed_at"}};for(var a:k)if(r.containsKey(a[1]))x.put(a[0],r.get(a[1]));return x;}public record Submit(String completionNote,java.math.BigDecimal actualQuantity,List<String>proofUrls){}
}
